// X Social Momentum Scanner v7.1 - Build GetXAPI Queries
// Major changes from v5:
// - Targets GetXAPI (https://api.getxapi.com) instead of official X API.
// - ROTATING universe by default for cost control (~$15-30/mo at 30m cadence).
// - Market-hours gate: skips runs outside US trading + 1h pre/post.
// - Tweet ID de-dupe across runs to avoid paying for the same tweet twice.
// - Per-source tagging so we can attribute alpha back to each analyst handle.

const now = new Date();
const lookbackHours = 6; // shorter window since we run every 30m

// Pull persistent state (de-dupe cache + analyst attribution)
const staticData = $getWorkflowStaticData("global");
staticData.seenTweetIds = staticData.seenTweetIds || {};
staticData.analystAttribution = staticData.analystAttribution || {};
staticData.rotatingOffset = staticData.rotatingOffset || 0;

// Prune de-dupe cache to last 24h (tweet IDs older than that won't reappear in recent search)
const cacheCutoff = now.getTime() - 24 * 60 * 60 * 1000;
for (const id of Object.keys(staticData.seenTweetIds)) {
  if (staticData.seenTweetIds[id] < cacheCutoff) delete staticData.seenTweetIds[id];
}

const config = {
  version: "v7_1_LLM_Sentiment_Slippage_Fixed",
  provider: "getxapi",

  // ---- MARKET HOURS GATE ----
  // Run between 8am ET (1h before open) and 5pm ET (1h after close), Mon-Fri.
  // Trigger node still fires; we just emit zero queries off-hours.
  marketHours: {
    enabled: true,
    timezone: "America/New_York",
    startHourET: 8,
    endHourET: 17,
    weekdaysOnly: true
  },

  trustedHandles: [
    "unusual_whales", "OptionAlert", "Benzinga", "DeItaone", "StockMKTNewz",
    "Newsquawk", "financialjuice", "MarketWatch", "IBDinvestors", "BreakoutStocks",
    "WSJMarkets", "CNBCnow", "KobeissiLetter", "bespokeinvest", "LizAnnSonders",
    "RyanDetrick", "charliebilello", "allstarcharts", "alphatrends", "PeterLBrandt",
    "markminervini", "DanZanger", "TraderLion_", "traderstewie", "Qullamaggie",
    "SJosephBurns", "traderDanielle", "Stephanie_Link", "howardlindzon", "Ritholtz",
    "elerianm", "BrianFeroldi", "iancassel", "awealthofcs", "Stocktwits",
    "PiQSuite", "TrendSpider", "SpotGamma", "Options", "OptionsHawk"
  ],

  fallbackSymbols: [
    "NVDA","AMD","AVGO","MU","TSM","MRVL","ARM","INTC","QCOM","ALAB","ONTO","WDC",
    "AMAT","LRCX","KLAC","ASML","VRT","CRWD","NOW","ANET","SMCI","ORCL","PANW","NET","TSLA",
    "META","MSFT","GOOGL","APP","AMZN","PLTR","SNOW","SHOP","RDDT","DDOG","MDB","ZS","TTD","GTLB","NFLX","SPOT",
    "GEV","BE","CEG","CCJ","VST","SMR","OKLO","NEE","PWR","GNRC","HUBB",
    "LEU","NNE","UEC","FCX","MP","NEM","SCCO","WPM","BHP",
    "XOM","CVX","LNG","WMB","COP","SLB","TRGP","OKE","GS","JPM","MS","V","MA","HOOD",
    "LMT","NOC","RTX","GD","KTOS","LDOS","SAIC","HII","RCAT","VKTX","MRNA","REGN","INCY","RXRX",
    "COIN","MARA","MSTR","CLSK","RIOT","HUT","RKLB","LUNR","ASTS","IONQ"
  ],

  universeFilters: {
    exchanges: ["NYSE", "NASDAQ", "AMEX"],
    minPrice: 1,
    minMarketCap: 50000000, // raised slightly to reduce penny-stock pump risk
    maxSymbols: 6500,
    removeUnitsRightsWarrants: true,
    removeFundsEtfsPreferreds: true
  },

  apiControl: {
    // BALANCED mode: 1 analyst-feed query per run + ROTATING cashtag slice.
    // Slice = 600 symbols per run, full universe cycled ~every 5.5 hours during market hours.
    universeScanMode: "ROTATING",
    rotatingSliceSize: 600,
    maxGetXAPICashtagsPerQuery: 30, // GetXAPI advanced_search returns 20/page; keep query small
    maxPagesPerQuery: 1, // ~20 tweets per call. Don't paginate to keep cost predictable
    analystFeedBatchSize: 8 // 8 handles per OR-query, so ~5 queries for 40 handles
  },

  thresholds: {
    minScoreToShow: 55,
    actionableWatch: 80,
    watchForTrigger: 70,
    interesting: 60,
    minUniqueAuthorsForLong: 3,
    minRVOL: 1.5,
    noChasePct: 12,
    hardNoChasePct: 20,
    smallCapPumpRiskMarketCap: 300000000,
    maxNewTrackerIdeasPerRun: 8,
    maxTrackerDays: 10
  },

  // ---- PAPER TRADING CONFIG ----
  paperTrading: {
    enabled: true,
    startingCapital: 100000,
    maxPositionPct: 0.05,        // 5% of equity per trade
    maxOpenPositions: 10,
    stopLossPct: 0.06,           // 6% hard stop
    takeProfitPct: 0.15,         // 15% target
    trailingStopAfterPct: 0.08,  // start trailing once +8%
    trailingDistancePct: 0.04,
    maxHoldDays: 10,
    minDecisionGrade: "WATCH FOR TRIGGER" // only auto-paper-buy this or better
  }
};

// ---- MARKET HOURS GATE ----
function isMarketWindow() {
  if (!config.marketHours.enabled) return true;
  // Get ET hour. Use Intl rather than naive offsets to handle DST.
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: config.marketHours.timezone,
    hour: "numeric", hour12: false, weekday: "short"
  });
  const parts = fmt.formatToParts(now);
  const hour = parseInt(parts.find(p => p.type === "hour").value, 10);
  const weekday = parts.find(p => p.type === "weekday").value;
  const isWeekday = !["Sat", "Sun"].includes(weekday);
  const inHours = hour >= config.marketHours.startHourET && hour < config.marketHours.endHourET;
  return (!config.marketHours.weekdaysOnly || isWeekday) && inHours;
}

if (!isMarketWindow()) {
  return [{
    json: {
      skip: true,
      reason: "Outside US market window (8am-5pm ET, weekdays).",
      asOf: now.toISOString(),
      config
    }
  }];
}

// ---- UNIVERSE BUILD ----
function unwrapFmpUniverse(inputItems) {
  const rows = [];
  for (const item of inputItems || []) {
    const j = item.json;
    const body = j?.body || j;
    if (Array.isArray(body)) rows.push(...body);
    else if (Array.isArray(body?.data)) rows.push(...body.data);
    else if (Array.isArray(body?.results)) rows.push(...body.results);
  }
  return rows;
}

function toNum(x) {
  if (x === null || x === undefined || x === "") return null;
  const n = Number(String(x).replace(/,/g, ""));
  return Number.isFinite(n) ? n : null;
}

function buildUniverse(rows) {
  const f = config.universeFilters;
  const allowedExchanges = new Set(f.exchanges.map(x => x.toUpperCase()));
  const badName = /(ETF|ETN|TRUST|FUND|PREFERRED|PREF|WARRANT|RIGHT|UNIT|NOTES|DEPOSITARY)/i;
  const out = [];
  const seen = new Set();
  for (const row of rows || []) {
    const symbol = String(row.symbol || row.ticker || "").trim().toUpperCase();
    if (!symbol || seen.has(symbol)) continue;
    if (!/^[A-Z]{1,5}$/.test(symbol)) continue;
    const exchange = String(row.exchangeShortName || row.exchange || row.exchangeName || "").toUpperCase();
    if (exchange && !allowedExchanges.has(exchange)) continue;
    const name = String(row.companyName || row.name || "");
    if (f.removeUnitsRightsWarrants && /(WARRANT|RIGHT|UNIT)/i.test(name)) continue;
    if (f.removeFundsEtfsPreferreds && badName.test(name)) continue;
    const price = toNum(row.price);
    if (price !== null && price < f.minPrice) continue;
    const marketCap = toNum(row.marketCap);
    if (marketCap !== null && marketCap < f.minMarketCap) continue;
    seen.add(symbol);
    out.push(symbol);
    if (out.length >= f.maxSymbols) break;
  }
  return out;
}

function cleanHandles(handles) {
  return [...new Set(handles.map(h => String(h || "").replace("@","").trim()).filter(Boolean))];
}

function chunkArr(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

let symbolUniverse = buildUniverse(unwrapFmpUniverse($input.all()));
let universeSource = "FMP company-screener";
if (!symbolUniverse.length) {
  symbolUniverse = [...new Set(config.fallbackSymbols)];
  universeSource = "fallbackSymbols (FMP universe returned nothing)";
}

// Rotating slice (so we don't scan all 6500 in one run)
const sliceSize = config.apiControl.rotatingSliceSize;
const totalSym = symbolUniverse.length;
const startIdx = staticData.rotatingOffset % totalSym;
let scanSlice;
if (startIdx + sliceSize <= totalSym) {
  scanSlice = symbolUniverse.slice(startIdx, startIdx + sliceSize);
} else {
  scanSlice = symbolUniverse.slice(startIdx).concat(symbolUniverse.slice(0, sliceSize - (totalSym - startIdx)));
}
staticData.rotatingOffset = (startIdx + sliceSize) % totalSym;

config.symbolUniverse = symbolUniverse; // full list passed downstream for filtering ticker extraction
config.scanSliceSymbols = scanSlice;
config.universeSource = universeSource;
config.universeCount = symbolUniverse.length;
config.scanSliceSize = scanSlice.length;

// ---- BUILD GetXAPI QUERIES ----
// GetXAPI advanced_search uses the same operators as X (from:, OR, etc).
// Each call returns ~20 tweets and costs $0.001.
const items = [];
const handles = cleanHandles(config.trustedHandles);

// Q1: Analyst feed - split into batches of N handles per query
const handleBatches = chunkArr(handles, config.apiControl.analystFeedBatchSize);
for (const batch of handleBatches) {
  const fromClause = batch.map(h => `from:${h}`).join(" OR ");
  // GetXAPI uses Latest by default - that's what we want for live momentum
  const q = `(${fromClause}) (stock OR stocks OR shares OR calls OR puts OR breakout OR "price target" OR upgrade OR earnings OR catalyst OR squeeze OR buy OR watch OR long) lang:en -is:retweet`;
  items.push({
    json: {
      source_query_type: "analyst_feed",
      handles_in_query: batch,
      q,
      product: "Latest",
      config
    }
  });
}

// Q2: Cashtag scan over rotating slice (batched into reasonable-length queries)
const cashtagBatches = chunkArr(scanSlice.map(s => `$${s}`), config.apiControl.maxGetXAPICashtagsPerQuery);
for (const batch of cashtagBatches) {
  const q = `(${batch.join(" OR ")}) lang:en -is:retweet`;
  items.push({
    json: {
      source_query_type: "cashtag_rotation",
      q,
      product: "Latest",
      config
    }
  });
}

// Q3: Catalyst-keyword discovery (catches stocks outside the slice)
const discoveryQueries = [
  `("breakout" OR "unusual volume" OR "call sweep" OR "short squeeze" OR "FDA approval" OR "price target raised" OR "earnings beat") (stock OR shares OR calls OR $) lang:en -is:retweet`,
  `("watchlist" OR "scanner" OR "momentum" OR "relative volume" OR "gapper") (stock OR ticker OR $) lang:en -is:retweet`
];
for (const q of discoveryQueries) {
  items.push({
    json: {
      source_query_type: "keyword_discovery",
      q,
      product: "Latest",
      config
    }
  });
}

if (!items.length) {
  return [{ json: { skip: true, reason: "No queries built", config } }];
}
return items;

// X Social Momentum Scanner v6 - Parse GetXAPI Responses + Build FMP Request
// GetXAPI response shape (per docs):
//   { query, tweet_count, has_more, next_cursor, tweets: [
//     { id, url, text, retweetCount, replyCount, likeCount, quoteCount, viewCount,
//       createdAt, lang, isReply, author: { userName, id, isVerified, isBlueVerified,
//       followers, ... } }
//   ] }

const allResponses = $input.all().map(i => i.json);
const queryItems = $items("Build GetXAPI Queries").map(i => i.json);
const firstItem = queryItems[0] || {};

// Handle skip case from upstream
if (firstItem.skip) {
  return [{ json: { skip: true, reason: firstItem.reason, asOf: new Date().toISOString() } }];
}

const config = firstItem.config || {};
const universeSymbols = new Set((config.symbolUniverse || []).map(s => String(s).toUpperCase()));
const trusted = new Set((config.trustedHandles || []).map(h => String(h).replace("@","").toLowerCase()));

const staticData = $getWorkflowStaticData("global");
staticData.seenTweetIds = staticData.seenTweetIds || {};
staticData.analystAttribution = staticData.analystAttribution || {};

const STOPWORDS = new Set([
  "A","I","AI","AM","PM","CEO","CFO","USA","US","UK","EU","EPS","GDP","CPI","FOMC","SEC","FDA","IPO","ETF","ATH","HOD","LOD","RTH",
  "THE","AND","FOR","ARE","YOU","BUY","SELL","PUT","CALL","CALLS","PUTS","DD","ER","IT","OR","ON","IN","TO",
  "Q1","Q2","Q3","Q4","YOY","QOQ","ROI","ROE","PE","PT","TF","SL","TP","RSI","MA","EMA","SMA","VWAP","OPEX","JPOW"
]);

function getTweetsFromResponse(resp) {
  const body = resp?.body || resp;
  if (!body) return { tweets: [], error: "empty body" };
  if (body.error) return { tweets: [], error: body.error };
  // GetXAPI returns tweets directly under "tweets"
  const tweets = Array.isArray(body.tweets) ? body.tweets : [];
  return { tweets, error: null };
}

function extractSymbols(tweetText) {
  const out = new Set();
  const re = /\$([A-Z]{1,5})(?![A-Z])/g;
  let m;
  while ((m = re.exec(tweetText || "")) !== null) {
    const s = m[1].toUpperCase();
    if (!STOPWORDS.has(s)) out.add(s);
  }
  // Plain ticker only if in confirmed FMP universe (avoids false positives)
  const caps = String(tweetText || "").match(/\b[A-Z]{2,5}\b/g) || [];
  for (const raw of caps) {
    const s = raw.toUpperCase();
    if (!STOPWORDS.has(s) && universeSymbols.has(s)) out.add(s);
  }
  // STRICT: only return symbols that exist in the FMP universe.
  // This is a fix from v5 which let any <=5 char uppercase token through.
  return [...out].filter(s => universeSymbols.has(s));
}

function classifyReason(text) {
  const t = String(text || "").toLowerCase();
  const reasons = [];
  if (/breakout|breaking out|resistance|52.?week|all.time.high|ath|higher high|trendline/.test(t)) reasons.push("technical_breakout");
  if (/call sweep|calls|option|options|flow|premium|unusual option/.test(t)) reasons.push("options_flow_chatter");
  if (/earnings|guidance|beat|revenue|eps|margin/.test(t)) reasons.push("earnings_or_guidance");
  if (/upgrade|price target|pt raised|initiated|outperform|overweight/.test(t)) reasons.push("analyst_upgrade_or_pt");
  if (/short squeeze|squeeze|short interest|borrow|float/.test(t)) reasons.push("squeeze_chatter");
  if (/fda|phase [123]|trial|approval|pdufa|clinical|biotech/.test(t)) reasons.push("biotech_catalyst");
  if (/contract|partnership|deal|order|award|supply|customer/.test(t)) reasons.push("contract_or_partnership");
  if (/ai|gpu|datacenter|data center|semiconductor|chip|server|nuclear|power grid/.test(t)) reasons.push("theme_momentum");
  if (/insider|13g|13d|buyback|repurchase|filing/.test(t)) reasons.push("filing_or_insider");
  if (/pump|moon|100x|next runner|low float|explode|send it|to the moon|rocket/.test(t)) reasons.push("pump_language");
  if (!reasons.length) reasons.push("generic_stock_mention");
  return [...new Set(reasons)];
}

function compactText(text) {
  return String(text || "").replace(/\s+/g, " ").trim().slice(0, 280);
}

const stats = {};
const diagnostics = {
  responses: allResponses.length,
  tweets_seen: 0,
  tweets_deduped: 0,
  tweets_with_symbols: 0,
  api_errors: []
};

const nowMs = Date.now();

for (const resp of allResponses) {
  const { tweets, error } = getTweetsFromResponse(resp);
  if (error) diagnostics.api_errors.push(String(error).slice(0, 200));

  for (const tweet of tweets) {
    diagnostics.tweets_seen += 1;
    const tid = String(tweet.id || "");
    if (!tid) continue;
    if (staticData.seenTweetIds[tid]) {
      diagnostics.tweets_deduped += 1;
      continue;
    }
    staticData.seenTweetIds[tid] = nowMs;

    const author = tweet.author || {};
    const username = String(author.userName || "").toLowerCase();
    const text = tweet.text || "";
    const symbols = extractSymbols(text);
    if (!symbols.length) continue;
    diagnostics.tweets_with_symbols += 1;

    const engagement =
      (tweet.likeCount || 0) +
      (tweet.replyCount || 0) * 2 +
      (tweet.retweetCount || 0) * 2 +
      (tweet.quoteCount || 0) * 2;

    const isTrusted = trusted.has(username);
    const authorFollowers = author.followers || 0;
    const reasons = classifyReason(text);

    for (const sym of symbols) {
      if (!stats[sym]) {
        stats[sym] = {
          symbol: sym,
          mentionCount: 0,
          uniqueAuthors: [],
          trustedMentionAuthors: [], // <-- new: tracks WHICH analysts surfaced this
          trustedMentions: 0,
          engagement: 0,
          followersReachApprox: 0,
          reasonCounts: {},
          pumpLanguageHits: 0,
          samplePosts: []
        };
      }
      const row = stats[sym];
      row.mentionCount += 1;
      if (username && !row.uniqueAuthors.includes(username)) row.uniqueAuthors.push(username);
      if (isTrusted) {
        row.trustedMentions += 1;
        if (!row.trustedMentionAuthors.includes(username)) row.trustedMentionAuthors.push(username);
      }
      row.engagement += engagement;
      row.followersReachApprox += authorFollowers;
      for (const r of reasons) {
        row.reasonCounts[r] = (row.reasonCounts[r] || 0) + 1;
        if (r === "pump_language") row.pumpLanguageHits += 1;
      }
      if (row.samplePosts.length < 5) {
        row.samplePosts.push({
          tweetId: tid,
          author: username || "unknown",
          trusted: isTrusted,
          created_at: tweet.createdAt,
          engagement,
          text: compactText(text),
          reasons
        });
      }
    }
  }
}

function computeSocialScore(row) {
  const mention = Math.min(25, row.mentionCount * 4);
  const unique = Math.min(15, row.uniqueAuthors.length * 3);
  const engagement = Math.min(15, Math.log10(row.engagement + 1) * 5);
  const trustedScore = Math.min(20, row.trustedMentions * 10);
  const reach = Math.min(10, Math.log10(row.followersReachApprox + 10) * 2);
  const reasonStrength =
    (row.reasonCounts.technical_breakout ? 4 : 0) +
    (row.reasonCounts.options_flow_chatter ? 4 : 0) +
    (row.reasonCounts.earnings_or_guidance ? 4 : 0) +
    (row.reasonCounts.analyst_upgrade_or_pt ? 4 : 0) +
    (row.reasonCounts.biotech_catalyst ? 4 : 0) +
    (row.reasonCounts.contract_or_partnership ? 4 : 0);
  const penalty = Math.min(15, row.pumpLanguageHits * 5);
  return Math.max(0, Math.round(mention + unique + engagement + trustedScore + reach + Math.min(15, reasonStrength) - penalty));
}

let candidates = Object.values(stats).map(row => {
  const reasonsSorted = Object.entries(row.reasonCounts).sort((a,b) => b[1]-a[1]).map(([k]) => k);
  return {
    ...row,
    uniqueAuthorCount: row.uniqueAuthors.length,
    topReasons: reasonsSorted.slice(0, 5),
    socialScore: computeSocialScore(row)
  };
}).sort((a,b) => b.socialScore - a.socialScore || b.mentionCount - a.mentionCount);

candidates = candidates.slice(0, 30);
const symbols = candidates.map(c => c.symbol).filter(Boolean);
const symbols_csv = symbols.join(",");

return [{
  json: {
    asOf: new Date().toISOString(),
    source: "GetXAPI advanced_search",
    version: config.version || "v6",
    diagnostics,
    config,
    candidates,
    symbols,
    symbols_csv,
    skip: false
  }
}];

// v7 - Score Candidates only. No paper trading yet (happens after LLM gate).
const parseOut = $items("Parse GetXAPI Responses")[0]?.json || {};
if (parseOut.skip) {
  return [{ json: {
    skip: true,
    reason: parseOut.reason || "Upstream skipped",
    asOf: new Date().toISOString()
  }}];
}

const config = parseOut.config || {};
const thresholds = config.thresholds || {};
const candidates = parseOut.candidates || [];

function flattenNodeItems(name) {
  try {
    const raw = $items(name).map(i => i.json);
    if (raw.length === 1 && Array.isArray(raw[0])) return raw[0];
    return raw.flatMap(x => Array.isArray(x) ? x : [x]);
  } catch (e) { return []; }
}

const quoteRows = flattenNodeItems("FMP Batch Quote");
const newsRows = flattenNodeItems("FMP Stock News");

function symOfQuote(q) { return String(q.symbol || q.ticker || q.Symbol || "").toUpperCase(); }
const quoteMap = {};
for (const q of quoteRows) {
  const s = symOfQuote(q);
  if (s) quoteMap[s] = q;
}

const newsBySymbol = {};
for (const n of newsRows) {
  const rawSymbols = n.symbols || n.symbol || n.tickers || n.ticker || [];
  const arr = Array.isArray(rawSymbols) ? rawSymbols : String(rawSymbols || "").split(",");
  for (const s0 of arr) {
    const s = String(s0).replace("$","").trim().toUpperCase();
    if (!s) continue;
    if (!newsBySymbol[s]) newsBySymbol[s] = [];
    newsBySymbol[s].push({
      publishedDate: n.publishedDate || n.date || n.datetime,
      title: n.title || n.headline || "",
      site: n.site || n.publisher || "",
      url: n.url || n.link || ""
    });
  }
}

function toNum(v) {
  if (v === null || v === undefined) return null;
  const n = Number(String(v).replace(/[,%$]/g, ""));
  return Number.isFinite(n) ? n : null;
}
function pctFromQuote(q) {
  return toNum(q.changesPercentage ?? q.changePercentage ?? q.changePercent ?? q.percent_change ?? q.change);
}
function reasonText(reasons) {
  const map = {
    technical_breakout: "technical breakout chatter",
    options_flow_chatter: "options/call-flow chatter",
    earnings_or_guidance: "earnings/guidance discussion",
    analyst_upgrade_or_pt: "analyst upgrade/price-target discussion",
    squeeze_chatter: "short-squeeze chatter",
    biotech_catalyst: "biotech/FDA catalyst",
    contract_or_partnership: "contract/partnership catalyst",
    theme_momentum: "theme momentum",
    filing_or_insider: "filing/insider/buyback discussion",
    pump_language: "pump-language risk",
    generic_stock_mention: "generic mention"
  };
  return (reasons || []).map(r => map[r] || r).join(", ");
}

function scoreCandidate(c) {
  const q = quoteMap[c.symbol] || {};
  const price = toNum(q.price ?? q.close ?? q.previousClose);
  const changePct = pctFromQuote(q);
  const volume = toNum(q.volume);
  const avgVolume = toNum(q.avgVolume ?? q.averageVolume);
  const rvol = volume && avgVolume ? volume / avgVolume : null;
  const marketCap = toNum(q.marketCap);
  const priceAvg50 = toNum(q.priceAvg50 ?? q.priceAvg50d ?? q.ma50);
  const priceAvg200 = toNum(q.priceAvg200 ?? q.priceAvg200d ?? q.ma200);
  const news = newsBySymbol[c.symbol] || [];
  const hasRealNews = news.length > 0;

  let catalystScore = 0;
  if (hasRealNews) catalystScore += 12;
  if (c.topReasons?.some(r => ["earnings_or_guidance","analyst_upgrade_or_pt","biotech_catalyst","contract_or_partnership","filing_or_insider"].includes(r))) catalystScore += 8;
  catalystScore = Math.min(20, catalystScore);

  let technicalScore = 0;
  if (changePct !== null && changePct > 0) technicalScore += 4;
  if (rvol !== null && rvol >= (thresholds.minRVOL || 1.5)) technicalScore += 6;
  if (price && priceAvg50 && price > priceAvg50) technicalScore += 5;
  if (price && priceAvg200 && price > priceAvg200) technicalScore += 3;
  if (changePct !== null && changePct > (thresholds.noChasePct || 12)) technicalScore -= 4;
  technicalScore = Math.max(0, Math.min(18, technicalScore));

  const socialComponent = Math.min(45, Math.round((c.socialScore || 0) * 0.45));
  const totalScore = Math.round(socialComponent + catalystScore + technicalScore);

  const pumpFlags = [];
  if ((c.pumpLanguageHits || 0) > 0) pumpFlags.push("pump language detected");
  if (c.uniqueAuthorCount < (thresholds.minUniqueAuthorsForLong || 3)) pumpFlags.push("too few unique accounts");
  if (marketCap !== null && marketCap < (thresholds.smallCapPumpRiskMarketCap || 300000000)) pumpFlags.push("small-cap/low-float pump risk");
  if (changePct !== null && changePct >= (thresholds.hardNoChasePct || 20) && !hasRealNews) pumpFlags.push("already vertical without confirmed news");
  if (!hasRealNews && c.trustedMentions === 0 && c.socialScore < 70) pumpFlags.push("social-only, no trusted source/news confirmation");

  let decision = "IGNORE";
  if (pumpFlags.length >= 2) decision = "AVOID - PUMP RISK";
  else if (totalScore >= (thresholds.actionableWatch || 80)) decision = "ACTIONABLE WATCH";
  else if (totalScore >= (thresholds.watchForTrigger || 70)) decision = "WATCH FOR TRIGGER";
  else if (totalScore >= (thresholds.interesting || 60)) decision = "INTERESTING - NEEDS CONFIRMATION";
  else if (totalScore >= (thresholds.minScoreToShow || 55)) decision = "LOW PRIORITY WATCH";

  return {
    rank: 0,
    symbol: c.symbol,
    totalScore, socialScore: c.socialScore,
    mentionCount: c.mentionCount,
    uniqueAuthorCount: c.uniqueAuthorCount,
    trustedMentions: c.trustedMentions,
    trustedMentionAuthors: c.trustedMentionAuthors || [],
    engagement: c.engagement,
    whyXIsTalking: reasonText(c.topReasons),
    topReasons: c.topReasons,
    price, changePct, volume, avgVolume,
    rvol: rvol ? Number(rvol.toFixed(2)) : null,
    marketCap, hasRealNews,
    latestNews: news.slice(0, 3),
    pumpFlags, decision,
    samplePosts: c.samplePosts
  };
}

let ranked = candidates.map(scoreCandidate)
  .filter(x => x.totalScore >= (thresholds.minScoreToShow || 55) || x.decision.includes("PUMP"))
  .sort((a,b) => b.totalScore - a.totalScore);
ranked = ranked.map((x, i) => ({...x, rank: i + 1}));

// Identify which candidates need LLM review. Only top-scoring tradeable
// candidates get reviewed (cost control).
const llmReviewSet = new Set(
  ranked
    .filter(r => ["ACTIONABLE WATCH","WATCH FOR TRIGGER"].includes(r.decision))
    .slice(0, 15)
    .map(r => r.symbol)
);

return [{
  json: {
    asOf: new Date().toISOString(),
    config,
    ranked,
    llmReviewSymbols: [...llmReviewSet],
    quoteMap,
    newsBySymbol,
    skip: false
  }
}];

// v7 - Build one prompt item per candidate to send to Gemini.
// Cost: only top candidates that survived to "WATCH FOR TRIGGER" or better.

const scoreOut = $items("Score Candidates")[0]?.json || {};
if (scoreOut.skip) {
  return [{ json: { skip: true, passthrough: true, asOf: new Date().toISOString() } }];
}

const ranked = scoreOut.ranked || [];
const reviewSet = new Set(scoreOut.llmReviewSymbols || []);

const out = [];
for (const r of ranked) {
  if (!reviewSet.has(r.symbol)) continue;

  // Use up to 5 sample posts for context
  const samples = (r.samplePosts || []).slice(0, 5);
  const sampleText = samples
    .map((p, i) => `[${i+1}] @${p.author}${p.trusted ? " (trusted)" : ""}: ${p.text}`)
    .join("\n");

  const prompt = `You are a financial-sentiment classifier. Read tweets about a single stock and decide whether the OVERALL sentiment in the tweets is BULLISH (the authors expect the stock to go up), BEARISH (down), or NEUTRAL/UNCLEAR.

Stock: $${r.symbol}
Current price: ${r.price ?? "unknown"}
Change today: ${r.changePct ?? "unknown"}%
Has confirmed news: ${r.hasRealNews}
Topic categories detected: ${r.whyXIsTalking}

Tweets:
${sampleText}

Critical rules:
- If the tweets describe SELLING calls, taking profit, closing positions, calling a top, or naming a "fake breakout", treat as BEARISH or NEUTRAL even if positive words appear.
- If sarcasm or reversal language is used (e.g. "great earnings... NOT", "to the moon /s"), treat as BEARISH or NEUTRAL.
- If tweets describe the analyst SHORTING the stock, treat as BEARISH.
- If most tweets are just announcing news without taking a stance, treat as NEUTRAL.

Respond with ONLY a JSON object, no markdown, no commentary:
{"sentiment":"bullish|bearish|neutral","confidence":0.0-1.0,"reasoning":"one short sentence","contains_sarcasm_or_reversal":true|false,"mentions_selling_or_closing":true|false}`;

  out.push({
    json: {
      symbol: r.symbol,
      llmRequestBody: {
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          temperature: 0.1,
          maxOutputTokens: 200,
          responseMimeType: "application/json"
        }
      }
    }
  });
}

if (!out.length) {
  // No candidates worth reviewing. Pass through with empty verdicts.
  return [{ json: { skip_llm: true, passthrough: true, asOf: new Date().toISOString() } }];
}
return out;

// v7 - Merge Gemini responses with their source symbols by index.
// n8n HTTP node returns response body only; we pair it with the upstream prompt items.
const promptItems = $items("Build LLM Prompts").map(i => i.json);
const respItems = $input.all().map(i => i.json);

if (promptItems.length === 1 && (promptItems[0].skip_llm || promptItems[0].passthrough)) {
  return [{ json: { skip_llm: true, passthrough: true } }];
}

const out = [];
const n = Math.min(promptItems.length, respItems.length);
for (let i = 0; i < n; i++) {
  out.push({
    json: {
      symbol: promptItems[i].symbol,
      body: respItems[i]
    }
  });
}
return out;

// v7 - Paper trading with LLM sentiment gate, slippage, and short selling.
const scoreOut = $items("Score Candidates")[0]?.json || {};

if (scoreOut.skip) {
  return [{ json: {
    skip: true,
    reason: scoreOut.reason || "Upstream skipped",
    sheetsCandidates: [], sheetsPaperTrades: [],
    sheetsAnalystAlpha: [], sheetsPortfolio: [],
    sheetsLLMVerdicts: []
  }}];
}

const config = scoreOut.config || {};
const thresholds = config.thresholds || {};
const paperCfg = config.paperTrading || { enabled: false };
const ranked = scoreOut.ranked || [];
const quoteMap = scoreOut.quoteMap || {};

// ---- Collect LLM verdicts from upstream Gemini HTTP node ----
// Each Gemini response item has shape:
//   { symbol, body: { candidates: [{ content: { parts: [{ text: "<json>" }] } }] } }
// or if skip_llm: just passes through.
const llmItems = $items("Merge LLM Verdicts").map(i => i.json);
const verdicts = {}; // symbol -> verdict object

for (const item of llmItems) {
  // Skip the pass-through case
  if (item.skip_llm || item.passthrough) continue;
  const sym = item.symbol;
  if (!sym) continue;
  const body = item.body || item;
  // Gemini response path
  let rawText = "";
  try {
    rawText = body?.candidates?.[0]?.content?.parts?.[0]?.text || "";
  } catch (e) {}
  if (!rawText) continue;
  // Strip markdown fences if Gemini added them
  rawText = rawText.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/, "").trim();
  try {
    const v = JSON.parse(rawText);
    verdicts[sym] = {
      sentiment: String(v.sentiment || "neutral").toLowerCase(),
      confidence: Number(v.confidence) || 0,
      reasoning: String(v.reasoning || "").slice(0, 300),
      sarcasm: !!v.contains_sarcasm_or_reversal,
      mentionsSelling: !!v.mentions_selling_or_closing
    };
  } catch (e) {
    // Failed JSON parse - treat as neutral/unclear, do not trade
    verdicts[sym] = { sentiment: "neutral", confidence: 0, reasoning: "LLM parse failed", sarcasm: false, mentionsSelling: false };
  }
}

// ---- Portfolio + attribution state ----
const staticData = $getWorkflowStaticData("global");
staticData.paperPortfolio = staticData.paperPortfolio || {
  cash: paperCfg.startingCapital || 100000,
  equity: paperCfg.startingCapital || 100000,
  openPositions: [],
  closedTrades: [],
  history: []
};
staticData.analystAttribution = staticData.analystAttribution || {};
const portfolio = staticData.paperPortfolio;
const attribution = staticData.analystAttribution;

function toNum(v) {
  if (v === null || v === undefined) return null;
  const n = Number(String(v).replace(/[,%$]/g, ""));
  return Number.isFinite(n) ? n : null;
}

// ---- SLIPPAGE MODEL ----
// Applied to entry and exit fill prices. Long entries fill ABOVE quote,
// long exits fill BELOW quote. Shorts: opposite.
function slippageBps(marketCap) {
  if (!marketCap) return 100; // unknown cap -> assume small-cap risk
  if (marketCap >= 10e9) return 30;   // 0.3% large cap
  if (marketCap >= 1e9)  return 50;   // 0.5% mid cap
  if (marketCap >= 300e6) return 100; // 1% small cap
  return 200;                          // 2% micro cap
}
function applyEntrySlippage(quotePrice, marketCap, side) {
  const bps = slippageBps(marketCap);
  // LONG: pay UP (price + slip), SHORT: receive LESS (price - slip)
  const factor = side === "LONG" ? (1 + bps/10000) : (1 - bps/10000);
  return quotePrice * factor;
}
function applyExitSlippage(quotePrice, marketCap, side) {
  const bps = slippageBps(marketCap);
  // LONG exit: receive LESS, SHORT cover: pay MORE
  const factor = side === "LONG" ? (1 - bps/10000) : (1 + bps/10000);
  return quotePrice * factor;
}

// ---- MARK-TO-MARKET + EXIT CHECKS for open positions ----
const now = new Date();
const stillOpen = [];
const justClosed = [];

for (const pos of portfolio.openPositions) {
  const q = quoteMap[pos.symbol];
  const quotePrice = q ? toNum(q.price ?? q.close ?? q.previousClose) : null;
  if (!quotePrice) { stillOpen.push(pos); continue; }

  pos.currentPrice = quotePrice;
  pos.daysHeld = Math.max(0, Math.floor((now - new Date(pos.entryAt)) / (24*60*60*1000)));

  if (pos.side === "LONG") {
    pos.highestPrice = Math.max(pos.highestPrice || pos.entryPrice, quotePrice);
    pos.lowestPrice  = Math.min(pos.lowestPrice  || pos.entryPrice, quotePrice);
    pos.unrealizedPct = Number((((quotePrice - pos.entryPrice) / pos.entryPrice) * 100).toFixed(2));
    pos.unrealizedPnL = Number(((quotePrice - pos.entryPrice) * pos.shares).toFixed(2));

    const gainPct = (quotePrice - pos.entryPrice) / pos.entryPrice;
    if (gainPct >= paperCfg.trailingStopAfterPct && !pos.trailingActive) pos.trailingActive = true;
    if (pos.trailingActive) {
      const newTrail = pos.highestPrice * (1 - paperCfg.trailingDistancePct);
      pos.trailingStop = Math.max(pos.trailingStop || 0, newTrail);
    }

    let exitReason = null;
    if (quotePrice <= pos.stopPrice) exitReason = "STOP_LOSS";
    else if (quotePrice >= pos.targetPrice) exitReason = "TAKE_PROFIT";
    else if (pos.trailingActive && quotePrice <= pos.trailingStop) exitReason = "TRAILING_STOP";
    else if (pos.daysHeld >= paperCfg.maxHoldDays) exitReason = "TIME_EXIT";

    if (exitReason) {
      const exitFill = applyExitSlippage(quotePrice, pos.marketCap, "LONG");
      const proceeds = exitFill * pos.shares;
      portfolio.cash += proceeds;
      pos.exitPrice = exitFill;
      pos.exitAt = now.toISOString();
      pos.exitReason = exitReason;
      pos.realizedPct = Number((((exitFill - pos.entryPrice) / pos.entryPrice) * 100).toFixed(2));
      pos.realizedPnL = Number(((exitFill - pos.entryPrice) * pos.shares).toFixed(2));
      portfolio.closedTrades.push(pos);
      justClosed.push(pos);
      continue;
    }
  } else {
    // SHORT position
    pos.highestPrice = Math.max(pos.highestPrice || pos.entryPrice, quotePrice);
    pos.lowestPrice  = Math.min(pos.lowestPrice  || pos.entryPrice, quotePrice);
    // For shorts: profit when price falls
    pos.unrealizedPct = Number((((pos.entryPrice - quotePrice) / pos.entryPrice) * 100).toFixed(2));
    pos.unrealizedPnL = Number(((pos.entryPrice - quotePrice) * pos.shares).toFixed(2));

    // Trailing for shorts: as price falls, lower the buy-back trigger
    const gainPct = (pos.entryPrice - quotePrice) / pos.entryPrice;
    if (gainPct >= paperCfg.trailingStopAfterPct && !pos.trailingActive) pos.trailingActive = true;
    if (pos.trailingActive) {
      const newTrail = pos.lowestPrice * (1 + paperCfg.trailingDistancePct);
      pos.trailingStop = Math.min(pos.trailingStop || Infinity, newTrail);
    }

    let exitReason = null;
    if (quotePrice >= pos.stopPrice) exitReason = "STOP_LOSS";          // short stop = price above entry
    else if (quotePrice <= pos.targetPrice) exitReason = "TAKE_PROFIT"; // short target = price below entry
    else if (pos.trailingActive && quotePrice >= pos.trailingStop) exitReason = "TRAILING_STOP";
    else if (pos.daysHeld >= paperCfg.maxHoldDays) exitReason = "TIME_EXIT";

    if (exitReason) {
      const coverFill = applyExitSlippage(quotePrice, pos.marketCap, "SHORT");
      // To close a short: pay (coverCost - entryProceeds) = realized P&L
      const coverCost = coverFill * pos.shares;
      const realizedShortPnL = (pos.entryProceeds || (pos.entryPrice * pos.shares)) - coverCost;
      portfolio.cash += realizedShortPnL;
      pos.exitPrice = coverFill;
      pos.exitAt = now.toISOString();
      pos.exitReason = exitReason;
      pos.realizedPct = Number((((pos.entryPrice - coverFill) / pos.entryPrice) * 100).toFixed(2));
      pos.realizedPnL = Number(((pos.entryPrice - coverFill) * pos.shares).toFixed(2));
      portfolio.closedTrades.push(pos);
      justClosed.push(pos);
      continue;
    }
  }

  stillOpen.push(pos);
}

// Update attribution from closed trades
for (const pos of justClosed) {
  for (const handle of (pos.sourceHandles || [])) {
    attribution[handle] = attribution[handle] || { trades: 0, wins: 0, losses: 0, totalPnL: 0, totalPctReturn: 0, longs: 0, shorts: 0 };
    attribution[handle].trades += 1;
    attribution[handle].totalPnL += pos.realizedPnL;
    attribution[handle].totalPctReturn += pos.realizedPct;
    if (pos.realizedPnL > 0) attribution[handle].wins += 1; else attribution[handle].losses += 1;
    if (pos.side === "LONG") attribution[handle].longs += 1; else attribution[handle].shorts += 1;
  }
}

portfolio.openPositions = stillOpen;

// ---- OPEN NEW POSITIONS based on LLM verdicts ----
const opened = [];
const blocked = []; // for logging when LLM blocked a trade

if (paperCfg.enabled) {
  const openSymbols = new Set(portfolio.openPositions.map(p => p.symbol));

  for (const r of ranked) {
    if (portfolio.openPositions.length >= paperCfg.maxOpenPositions) break;
    if (!["ACTIONABLE WATCH","WATCH FOR TRIGGER"].includes(r.decision)) continue;
    if (!r.price) continue;
    if (openSymbols.has(r.symbol)) continue;

    const verdict = verdicts[r.symbol];
    if (!verdict) {
      blocked.push({ symbol: r.symbol, reason: "no_llm_verdict", decision: r.decision });
      continue;
    }

    // Decide side
    let side = null;
    if (verdict.sentiment === "bullish" && verdict.confidence >= 0.6 && !verdict.sarcasm && !verdict.mentionsSelling) {
      // Standard long gate
      if (r.pumpFlags.length >= 1) {
        blocked.push({ symbol: r.symbol, reason: "long_blocked_by_pumpflag", verdict, decision: r.decision });
        continue;
      }
      if (r.changePct !== null && r.changePct >= (thresholds.noChasePct || 12)) {
        blocked.push({ symbol: r.symbol, reason: "long_blocked_no_chase", verdict, decision: r.decision });
        continue;
      }
      side = "LONG";
    } else if (verdict.sentiment === "bearish" && verdict.confidence >= 0.6) {
      // Short gate - we want bearish on a stock that's UP or recently strong (otherwise no juice)
      // Block shorts on very small caps (HTB risk too high)
      if (r.marketCap && r.marketCap < 500e6) {
        blocked.push({ symbol: r.symbol, reason: "short_blocked_microcap_htb", verdict, decision: r.decision });
        continue;
      }
      // Block if stock is already DOWN heavily today (no edge left)
      if (r.changePct !== null && r.changePct <= -10) {
        blocked.push({ symbol: r.symbol, reason: "short_blocked_already_down", verdict, decision: r.decision });
        continue;
      }
      // Block on price < $5 (real brokers often won't short)
      if (r.price < 5) {
        blocked.push({ symbol: r.symbol, reason: "short_blocked_under_5", verdict, decision: r.decision });
        continue;
      }
      side = "SHORT";
    } else {
      blocked.push({ symbol: r.symbol, reason: `llm_${verdict.sentiment}_conf_${verdict.confidence.toFixed(2)}`, verdict, decision: r.decision });
      continue;
    }

    // Compute equity and position size
    const openMTM = portfolio.openPositions.reduce((sum, p) => {
      const positionValue = (p.currentPrice || p.entryPrice) * p.shares;
      // LONG: value of shares held. SHORT: unrealized P&L = entryProceeds - currentLiability.
      return sum + (p.side === "LONG" ? positionValue : (p.entryProceeds - positionValue));
    }, 0);
    const equity = portfolio.cash + openMTM;
    const positionDollars = equity * paperCfg.maxPositionPct;
    if (positionDollars > portfolio.cash) continue;

    // Apply entry slippage
    const entryFill = applyEntrySlippage(r.price, r.marketCap, side);
    const shares = Math.floor(positionDollars / entryFill);
    if (shares < 1) continue;

    if (side === "LONG") {
      const cost = shares * entryFill;
      portfolio.cash -= cost;
      portfolio.openPositions.push({
        side: "LONG",
        symbol: r.symbol,
        entryAt: now.toISOString(),
        entryQuotePrice: r.price,
        entryPrice: Number(entryFill.toFixed(4)),
        slippageBps: slippageBps(r.marketCap),
        shares, cost: Number(cost.toFixed(2)),
        stopPrice: Number((entryFill * (1 - paperCfg.stopLossPct)).toFixed(4)),
        targetPrice: Number((entryFill * (1 + paperCfg.takeProfitPct)).toFixed(4)),
        currentPrice: r.price, highestPrice: r.price, lowestPrice: r.price,
        unrealizedPct: 0, unrealizedPnL: 0, daysHeld: 0,
        trailingActive: false, trailingStop: null,
        marketCap: r.marketCap,
        sourceHandles: r.trustedMentionAuthors || [],
        sourceDecision: r.decision, sourceScore: r.totalScore, sourceReasons: r.whyXIsTalking,
        hasRealNews: r.hasRealNews,
        llmSentiment: verdict.sentiment, llmConfidence: verdict.confidence, llmReasoning: verdict.reasoning,
        borrowRiskFlag: false
      });
      opened.push(portfolio.openPositions[portfolio.openPositions.length - 1]);
    } else {
      // SHORT: track entryProceeds as the cash we owe back when we cover.
      // We do NOT modify portfolio.cash on open: the proceeds from short sale
      // exactly offset the borrow liability for accounting purposes.
      // P&L is realized only when we cover.
      const entryProceeds = shares * entryFill;
      const htbRisk = (r.marketCap && r.marketCap < 2e9) || r.pumpFlags.some(f => f.includes("squeeze"));
      portfolio.openPositions.push({
        side: "SHORT",
        symbol: r.symbol,
        entryAt: now.toISOString(),
        entryQuotePrice: r.price,
        entryPrice: Number(entryFill.toFixed(4)),
        slippageBps: slippageBps(r.marketCap),
        shares,
        entryProceeds: Number(entryProceeds.toFixed(2)),
        // For shorts: stop ABOVE entry (we lose if price rises), target BELOW
        stopPrice: Number((entryFill * (1 + paperCfg.stopLossPct)).toFixed(4)),
        targetPrice: Number((entryFill * (1 - paperCfg.takeProfitPct)).toFixed(4)),
        currentPrice: r.price, highestPrice: r.price, lowestPrice: r.price,
        unrealizedPct: 0, unrealizedPnL: 0, daysHeld: 0,
        trailingActive: false, trailingStop: null,
        marketCap: r.marketCap,
        sourceHandles: r.trustedMentionAuthors || [],
        sourceDecision: r.decision, sourceScore: r.totalScore, sourceReasons: r.whyXIsTalking,
        hasRealNews: r.hasRealNews,
        llmSentiment: verdict.sentiment, llmConfidence: verdict.confidence, llmReasoning: verdict.reasoning,
        borrowRiskFlag: htbRisk
      });
      opened.push(portfolio.openPositions[portfolio.openPositions.length - 1]);
    }
    openSymbols.add(r.symbol);
  }
}

// Recompute equity
const openMTM = portfolio.openPositions.reduce((sum, p) => {
  const positionValue = (p.currentPrice || p.entryPrice) * p.shares;
  if (p.side === "LONG") return sum + positionValue;
  // SHORT unrealized P&L = entryProceeds - currentLiability
  return sum + (p.entryProceeds - positionValue);
}, 0);
portfolio.equity = Number((portfolio.cash + openMTM).toFixed(2));

portfolio.history.push({
  asOf: now.toISOString(),
  equity: portfolio.equity,
  cash: Number(portfolio.cash.toFixed(2)),
  openCount: portfolio.openPositions.length,
  openedThisRun: opened.length,
  closedThisRun: justClosed.length,
  blockedByLLM: blocked.length
});
portfolio.history = portfolio.history.slice(-2000);
portfolio.closedTrades = portfolio.closedTrades.slice(-500);

// ---- SHEETS ROWS ----
const runStamp = now.toISOString();

const sheetsCandidates = ranked.map(r => {
  const v = verdicts[r.symbol] || {};
  return {
    asOf: runStamp, rank: r.rank, ticker: r.symbol,
    totalScore: r.totalScore, socialScore: r.socialScore,
    decision: r.decision, whyXIsTalking: r.whyXIsTalking,
    mentionCount: r.mentionCount, uniqueAuthorCount: r.uniqueAuthorCount,
    trustedMentions: r.trustedMentions,
    trustedAuthors: (r.trustedMentionAuthors || []).join("; "),
    price: r.price, changePct: r.changePct, rvol: r.rvol, marketCap: r.marketCap,
    hasRealNews: r.hasRealNews, pumpFlags: r.pumpFlags.join("; "),
    llmSentiment: v.sentiment || "", llmConfidence: v.confidence || "", llmReasoning: v.reasoning || "",
    llmSarcasm: v.sarcasm || false, llmMentionsSelling: v.mentionsSelling || false,
    newsTitle1: r.latestNews?.[0]?.title || "", newsUrl1: r.latestNews?.[0]?.url || "",
    samplePost1: r.samplePosts?.[0]?.text || ""
  };
});

const formatTradeRow = (p, eventType) => ({
  asOf: runStamp, eventType,
  side: p.side, symbol: p.symbol,
  entryAt: p.entryAt, entryQuotePrice: p.entryQuotePrice, entryPrice: p.entryPrice,
  slippageBps: p.slippageBps, shares: p.shares,
  stopPrice: p.stopPrice, targetPrice: p.targetPrice,
  exitAt: p.exitAt || "", exitPrice: p.exitPrice || "",
  exitReason: p.exitReason || "",
  realizedPct: p.realizedPct ?? "", realizedPnL: p.realizedPnL ?? "",
  daysHeld: p.daysHeld || 0,
  borrowRiskFlag: p.borrowRiskFlag || false,
  marketCap: p.marketCap,
  sourceHandles: (p.sourceHandles || []).join("; "),
  sourceDecision: p.sourceDecision, sourceScore: p.sourceScore, sourceReasons: p.sourceReasons,
  hasRealNews: p.hasRealNews,
  llmSentiment: p.llmSentiment, llmConfidence: p.llmConfidence, llmReasoning: p.llmReasoning
});
const sheetsPaperTrades = [
  ...opened.map(p => formatTradeRow(p, "OPEN")),
  ...justClosed.map(p => formatTradeRow(p, "CLOSE"))
];

const sheetsAnalystAlpha = Object.entries(attribution).map(([handle, s]) => ({
  asOf: runStamp, handle,
  trades: s.trades, wins: s.wins, losses: s.losses,
  longs: s.longs || 0, shorts: s.shorts || 0,
  winRate: s.trades ? Number(((s.wins / s.trades) * 100).toFixed(1)) : 0,
  avgPctReturn: s.trades ? Number((s.totalPctReturn / s.trades).toFixed(2)) : 0,
  totalPnL: Number(s.totalPnL.toFixed(2))
})).sort((a,b) => b.avgPctReturn - a.avgPctReturn);

const sheetsPortfolio = [{
  asOf: runStamp,
  equity: portfolio.equity, cash: Number(portfolio.cash.toFixed(2)),
  openCount: portfolio.openPositions.length,
  longCount: portfolio.openPositions.filter(p => p.side === "LONG").length,
  shortCount: portfolio.openPositions.filter(p => p.side === "SHORT").length,
  openedThisRun: opened.length, closedThisRun: justClosed.length,
  blockedByLLM: blocked.length,
  totalClosedTrades: portfolio.closedTrades.length,
  startingCapital: paperCfg.startingCapital,
  totalReturnPct: Number((((portfolio.equity - paperCfg.startingCapital) / paperCfg.startingCapital) * 100).toFixed(2))
}];

const sheetsLLMVerdicts = Object.entries(verdicts).map(([sym, v]) => ({
  asOf: runStamp, symbol: sym,
  sentiment: v.sentiment, confidence: v.confidence,
  reasoning: v.reasoning, sarcasm: v.sarcasm,
  mentionsSelling: v.mentionsSelling
}));

return [{
  json: {
    asOf: runStamp,
    system: "X Social Momentum Scanner v7",
    rankedCandidates: ranked,
    verdicts, blocked,
    paperPortfolio: {
      cash: portfolio.cash, equity: portfolio.equity,
      openCount: portfolio.openPositions.length,
      openPositions: portfolio.openPositions,
      openedThisRun: opened, closedThisRun: justClosed
    },
    analystAttribution: attribution,
    sheetsCandidates, sheetsPaperTrades,
    sheetsAnalystAlpha, sheetsPortfolio, sheetsLLMVerdicts,
    skip: false
  }
}];
